import{z as s,x as i,o as t,c as p,q as r,j as l,D as a,d as A,s as n,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"局限与前沿","description":"","frontmatter":{"title":"局限与前沿","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-limits-frontier.md","filePath":"llm/xai-limits-frontier.md","lastUpdated":1791063341000}'),C={name:"llm/xai-limits-frontier.md"};function D(F,E,d,m,g,h){const e=i("Mermaid");return t(),p("div",null,[E[2]||(E[2]=r('<h1 id="局限与前沿" tabindex="-1">局限与前沿 <a class="header-anchor" href="#局限与前沿" aria-label="Permalink to &quot;局限与前沿&quot;">​</a></h1><div class="epigraph"><p>解释产生证据，不产生证明；看清这条方法链在哪些地方必然断开，才知道哪些结论可以出、哪些话永远不能说。</p><footer>—— 据 Templeton et al., 2024 的不完备声明与 Elhage et al., 2021 的方法框架整理</footer></div><p><a href="/llm/xai-toolchain-repro">上一课</a>把口径钉成了规范。规范管「是不是同一个实验」，管不了方法本身的断点。本课程第九课，把前八课在各自边界里露头的限制收拢成一张全局清单，再给当前的前沿各归其位。每条断点说明它为什么是<strong>硬限</strong>而非工程债，前沿说明它补的是哪条缝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>判定「解释成立」没有自动判据：释义、干预、归因图都产出证据，不产出证明。具体展开是四条。</p><p><strong>完备性未知。</strong> 字典没覆盖的方向照旧活在前向里，全部漏进误差节点；Templeton 等人 2024 年在公开报告里明确承认特征集不完备。误差占比随宽度下降是健康信号，但不等于归零，更不等于「剩下的不重要」。</p><p><span class="marginnote">「误差节点」可以理解成垃圾桶：字典解释不掉的那部分计算全被记到它头上。给个读法——如果一张电路图里误差节点吃掉了四成的贡献，等于这张图只交代了六成的行为来源，任何结论都该按比例打折；所以规范的图必须连误差占比一起报。</span></p><p><strong>忠实性无检验。</strong> 替换模型上的因果不等于原模型上的因果：转码器与字典是代理，代理算得通的故事，原模型未必在用——两个模型的干预不一致时，应报替换误差而不是挑好听的讲。</p><p><strong>循环性。</strong> 用大模型解释大模型，评分闭环内的一切一致都可能是解释器的先验；协议能压（第 2 课），压不到零。</p><p><strong>本体论不稳与成本集中。</strong> 特征编号绑定具体字典与 checkpoint；前沿级字典与追踪的训练费只有少数机构付得起——开放生态在补，但公共字典的覆盖面远小于私有模型的总量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前沿按补的是哪条缝归位。补<strong>完备性</strong>的：更大的字典与缩放律、跨层转码器与交叉层字典——让一个概念不必在每层复制一份；补<strong>忠实性</strong>的：替换误差显式入账（<a href="/llm/circuit-tracing">Circuit Tracing 课</a>的做法）、替换模型干预与原模型修补的双向核对；补<strong>循环性</strong>的：释义协议化——激活预测评分、留出集、换域重测变成工具默认（第 2 课的协议正在变成评测层组件）；补<strong>覆盖</strong>的：开放套件与特征浏览器把私有纵轴变成公共纵轴。</p><p>另有两条在缝外的方向值得点名：注意力侧的归因自动化——现有追踪偏重 MLP 与残差，「为何看向那个位置」的 QK 通路刚开始进入同一套工具；以及解释学和安全论证的接口——监控（第 5 课）与机制评测（第 7 课）是解释学变成安全论据的两条通道，目前都到不了「证明」级。</p>',13)),(t(),l(o,null,{default:a(()=>[n(e,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIMITS%5B%22%E5%9B%9B%E6%9D%A1%E7%A1%AC%E9%99%90%22%5D%20--%3E%20COMP%5B%22%E5%AE%8C%E5%A4%87%E6%80%A7%EF%BC%9A%E5%AD%97%E5%85%B8%E5%A4%96%E6%96%B9%E5%90%91%22%5D%0A%20%20LIMITS%20--%3E%20FAITH%5B%22%E5%BF%A0%E5%AE%9E%E6%80%A7%EF%BC%9A%E6%9B%BF%E6%8D%A2%E6%A8%A1%E5%9E%8B%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20LIMITS%20--%3E%20CIRC%5B%22%E5%BE%AA%E7%8E%AF%E6%80%A7%EF%BC%9A%E8%A7%A3%E9%87%8A%E5%99%A8%E5%85%88%E9%AA%8C%22%5D%0A%20%20LIMITS%20--%3E%20ONTO%5B%22%E6%9C%AC%E4%BD%93%E8%AE%BA%E4%B8%8D%E7%A8%B3%20%2B%20%E6%88%90%E6%9C%AC%E9%9B%86%E4%B8%AD%22%5D%0A%20%20COMP%20--%3E%20F1%5B%22%E5%89%8D%E6%B2%BF%EF%BC%9A%E8%B7%A8%E5%B1%82%E5%AD%97%E5%85%B8%20%2F%20%E7%BC%A9%E6%94%BE%E5%BE%8B%22%5D%0A%20%20FAITH%20--%3E%20F2%5B%22%E5%89%8D%E6%B2%BF%EF%BC%9A%E8%AF%AF%E5%B7%AE%E5%85%A5%E8%B4%A6%20%2B%20%E5%8F%8C%E5%90%91%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CIRC%20--%3E%20F3%5B%22%E5%89%8D%E6%B2%BF%EF%BC%9A%E9%87%8A%E4%B9%89%E5%8D%8F%E8%AE%AE%E5%8C%96%22%5D%0A%20%20ONTO%20--%3E%20F4%5B%22%E5%89%8D%E6%B2%BF%EF%BC%9A%E5%BC%80%E6%94%BE%E5%A5%97%E4%BB%B6%E5%85%AC%E5%85%B1%E7%BA%B5%E8%BD%B4%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[A("这四条为什么是硬限而非工程债，各有一条机制理由。完备性受"),B("strong",null,"表示本身"),A("限制：若叠加无限密，任何有限字典都丢信息，加宽度只是降低丢失率。忠实性受"),B("strong",null,"代理原理"),A("限制：替换模型的全部意义就是把不可解释组件换掉，换掉的那一刻，误差就与解释同在。循环性受"),B("strong",null,"同类解释者"),A("限制：解释器与被解释者共享训练分布与先验，一致性证据永远混着先验的份额。本体论不稳受"),B("strong",null,"方法论选择"),A("限制：特征是字典的函数，字典是一次工程决定——除非模型「本来」就按这个字典分解，而这恰是无法保证的事。")],-1)),(t(),l(o,null,{default:a(()=>[n(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%A2%AB%E8%A7%A3%E9%87%8A%E7%9A%84%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20D%5B%22%E5%AD%97%E5%85%B8%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%B7%A5%E7%A8%8B%E5%86%B3%E5%AE%9A%EF%BC%88%E6%9C%AC%E4%BD%93%E8%AE%BA%E4%B8%8D%E7%A8%B3%EF%BC%89%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%AF%AF%E5%B7%AE%E8%8A%82%E7%82%B9%EF%BC%9A%E5%AD%97%E5%85%B8%E5%A4%96%E6%96%B9%E5%90%91%EF%BC%88%E5%AE%8C%E5%A4%87%E6%80%A7%E6%9C%AA%E7%9F%A5%EF%BC%89%22%5D%0A%20%20D%20--%3E%20P%5B%22%E6%9B%BF%E6%8D%A2%E6%A8%A1%E5%9E%8B%20%2B%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%0A%20%20P%20--%3E%20C%5B%22%E4%B8%80%E8%87%B4%E5%8F%AF%E8%83%BD%E6%B7%B7%E7%9D%80%E8%A7%A3%E9%87%8A%E5%99%A8%E5%85%88%E9%AA%8C%EF%BC%88%E5%BE%AA%E7%8E%AF%E6%80%A7%EF%BC%89%22%5D%0A%20%20P%20--%3E%20I%5B%22%E5%B9%B2%E9%A2%84%E4%B8%8E%E5%BD%92%E5%9B%A0%E8%AF%81%E6%8D%AE%22%5D%0A%20%20I%20--%3E%20F%5B%22%E4%BB%A3%E7%90%86%E4%B8%8A%E7%9A%84%E5%9B%A0%E6%9E%9C%20%E2%89%A0%20%E5%8E%9F%E6%A8%A1%E5%9E%8B%E5%9B%A0%E6%9E%9C%EF%BC%88%E5%BF%A0%E5%AE%9E%E6%80%A7%EF%BC%89%22%5D%0A%20%20I%20--%3E%20G%7B%22%E7%BB%93%E8%AE%BA%E8%83%BD%E5%86%99%E5%88%B0%E5%93%AA%E4%B8%80%E6%AD%A5%EF%BC%9F%22%7D%0A%20%20G%20--%3E%7C%E5%81%87%E8%AE%BE%E7%94%9F%E6%88%90%20%2F%20%E9%A3%8E%E9%99%A9%E6%8E%A2%E6%B5%8B%20%2F%20%E8%AE%AD%E7%BB%83%E5%B7%A5%E5%85%B7%7C%20OK%5B%22%E6%AD%A3%E5%BD%93%E4%BA%A7%E5%87%BA%22%5D%0A%20%20G%20--%3E%7C%E3%80%8C%E6%A8%A1%E5%9E%8B%E6%97%A0%E5%AE%B3%E3%80%8D%E8%AF%81%E4%B9%A6%7C%20NO%5B%22%E8%B6%8A%E7%95%8C%EF%BC%9A%E5%9B%9B%E6%9D%A1%E7%A1%AC%E9%99%90%E5%85%B1%E5%90%8C%E7%A6%81%E6%AD%A2%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">「替换模型」用类比理解：为解释一台焊死的老旧发动机，先造一台透明外壳的教具复制品。教具上的油路图讲得再通，也不证明原件真是这么运转的——两者行为的差距就是「替换误差」。解释学的大多数结论发生在教具上，所以「代理算得通」永远要和「原模型是否真在用」分开说。</span></p><p>由此得出使用判据：解释性产出的正当角色是<strong>假设生成器、风险探测器、训练工具</strong>；把同一产出当成「模型无害」的证书，是这四条硬限共同禁止的越界。</p><p><span class="marginnote">把 Templeton et al., 2024 的自认贴在任何解释性产出的首页：特征集不完备、缺少「字典忠实刻画计算」的严格检验。这句话防住的过度声明，比整章方法论加起来还多。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的清单本身有时效：硬限随方法演进，今天的缝可能是明天的组件；不变的判断标准只有一条——任何应用方案都应说明自己在哪条缝上承担风险、用哪种证据垫底。课程不覆盖的相邻方向（表示几何、因果抽象）不在此展开。最后一条边界是社会的而非数学的：解释能力的成本集中意味着「谁能解释模型」本身是权力；开放生态是对策，也是它自己的新问题。</p><p><span class="marginnote">为什么重要：当前沿级字典与追踪训练只有少数机构付得起，「谁能解释模型」就成了少数人的审计特权——外部人只能接受「他们报告的结论」，无法自行复核。这就是开放套件、公共字典被视为公共品而不是慈善项目的原因：解释能力的可复核性，直接决定安全论证由谁监督。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四条硬限：完备性未知、忠实性无检验、循环性压不到零、本体论不稳加成本集中。</li><li>每条硬限有机制理由，分别卡在表示、代理原理、同类解释者与工程决定上。</li><li>前沿按补缝归位：跨层字典、误差入账、释义协议化、公共字典。</li><li>解释性产出是假设、探测器与工具；不是「模型无害」的证书。</li><li>出处：Templeton et al., 2024（不完备声明）；Elhage et al., 2021（方法框架）；Ameisen et al., 2025（追踪流水线）。</li></ul>',8))])}const T=s(C,[["render",D]]);export{u as __pageData,T as default};
